package engine

import "testing"

func TestDevicesAndPlatformObjects(t *testing.T) {
	tab := platformTab(t)
	runJSCases(t, tab, []jsCase{
		{"screen.orientation", `const o = screen.orientation; return [o instanceof ScreenOrientation, o instanceof EventTarget, o === screen.orientation, /^(landscape|portrait)-primary$/.test(o.type), o.angle, String(o), o.onchange];`, `[true,true,true,true,0,"[object ScreenOrientation]",null]`},
		{"orientation lock rejects", `const out = []; for (const a of ['landscape', 'portrait-primary']) { try { await screen.orientation.lock(a); out.push('ok'); } catch (e) { out.push(e.name); } } try { await screen.orientation.lock('diagonal'); } catch (e) { out.push(e.name); } try { await screen.orientation.lock(); } catch (e) { out.push(e.name); } return [out, screen.orientation.unlock()];`, `[["NotSupportedError","NotSupportedError","TypeError","TypeError"],null]`},
		{"orientation change handler can be set", `let n = 0; screen.orientation.onchange = () => n++; screen.orientation.dispatchEvent(new Event('change')); screen.orientation.onchange = null; screen.orientation.dispatchEvent(new Event('change')); return n;`, `1`},
		{"DeviceOrientationEvent", `const e = new DeviceOrientationEvent('deviceorientation', { alpha: 1, beta: 2, gamma: 3, absolute: true }); const d = new DeviceOrientationEvent('x'); return [e.alpha, e.beta, e.gamma, e.absolute, d.alpha, d.absolute, e instanceof Event, await DeviceOrientationEvent.requestPermission()];`, `[1,2,3,true,null,false,true,"denied"]`},
		{"DeviceMotionEvent", `const e = new DeviceMotionEvent('devicemotion', { acceleration: { x: 1, y: 2, z: 3 }, rotationRate: { alpha: 4 }, interval: 16 }); const d = new DeviceMotionEvent('x'); return [e.acceleration.x, e.acceleration.z, e.accelerationIncludingGravity, e.rotationRate.alpha, e.rotationRate.beta, e.interval, d.acceleration, d.interval, await DeviceMotionEvent.requestPermission(), e.acceleration instanceof DeviceMotionEventAcceleration];`, `[1,3,null,4,null,16,null,0,"denied",true]`},
		{"sensor events never fire", `let n = 0; addEventListener('deviceorientation', () => n++); addEventListener('devicemotion', () => n++); await new Promise(r => setTimeout(r, 30)); return n;`, `0`},
		{"gamepads", `const a = navigator.getGamepads(); const b = navigator.getGamepads(); const e = new GamepadEvent('gamepadconnected', { gamepad: {} }); let bad; try { new GamepadEvent('x'); } catch (x) { bad = x.name; } return [a, a === b, e.gamepad !== null, e instanceof Event, bad, typeof Gamepad, 'ongamepadconnected' in window || true];`, `[[null,null,null,null],false,true,true,"TypeError","function",true]`},
		{"wake lock", `const s = await navigator.wakeLock.request('screen'); const out = [s instanceof WakeLockSentinel, s.type, s.released, navigator.wakeLock instanceof WakeLock]; let fired = 0; s.onrelease = () => fired++; const a = await s.release(); await s.release(); out.push(a, s.released, fired); const d = await navigator.wakeLock.request(); out.push(d.type); try { await navigator.wakeLock.request('system'); } catch (e) { out.push(e.name); } return out;`, `[true,"screen",false,true,null,true,1,"screen","TypeError"]`},
		{"wake lock release listeners", `const s = await navigator.wakeLock.request(); const seen = []; s.addEventListener('release', e => seen.push(e.type)); await s.release(); return seen;`, `["release"]`},
		{"media session metadata", `const ms = navigator.mediaSession; const before = [ms.metadata, ms.playbackState]; ms.metadata = new MediaMetadata({ title: 'T', artist: 'A', album: 'B', artwork: [{ src: '/a.png', sizes: '96x96', type: 'image/png' }] }); const m = ms.metadata; const r = [before, m.title, m.artist, m.album, m.artwork.length, m.artwork[0].src.endsWith('/a.png'), m.artwork[0].src.startsWith('http'), m.artwork[0].sizes, m instanceof MediaMetadata]; m.title = 'T2'; r.push(ms.metadata.title); ms.metadata = null; r.push(ms.metadata); return r;`, `[[null,"none"],"T","A","B",1,true,true,"96x96",true,"T2",null]`},
		{"media session validation", `const ms = navigator.mediaSession; const out = []; for (const f of [() => { ms.metadata = {}; }, () => ms.setActionHandler('dance', () => { }), () => ms.setActionHandler('play', 5), () => new MediaMetadata({ artwork: [{}] }), () => new MediaMetadata({ artwork: 5 }), () => ms.setPositionState({ duration: 10, position: 20 })]) { try { f(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError","TypeError","TypeError","TypeError","TypeError"]`},
		{"media session handlers and state", `const ms = navigator.mediaSession; const h = () => 1; ms.setActionHandler('play', h); const got = ms.getActionHandler('play') === h; ms.setActionHandler('play', null); ms.playbackState = 'playing'; ms.playbackState = 'bogus'; ms.setPositionState({ duration: 100, position: 5, playbackRate: 2 }); ms.setPositionState(); return [got, ms.getActionHandler('play'), ms.playbackState, String(ms), String(new MediaMetadata())];`, `[true,null,"playing","[object MediaSession]","[object MediaMetadata]"]`},
		{"credentials without a provider", `const c = navigator.credentials; const out = [c instanceof CredentialsContainer, await c.get({ password: true }), await c.get(), await c.preventSilentAccess()]; for (const f of [() => c.get({ publicKey: { challenge: new Uint8Array(4) } }), () => c.create({ publicKey: {} }), () => c.create({ password: { id: 'a', password: 'b' } }), () => c.store({}), () => c.get(5)]) { try { await f(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `[true,null,null,null,"NotAllowedError","NotAllowedError","NotAllowedError","TypeError","TypeError"]`},
		{"credentials abort signal", `const ac = new AbortController(); ac.abort('stop'); try { await navigator.credentials.get({ signal: ac.signal }); } catch (e) { return e; }`, `"stop"`},
		{"PublicKeyCredential statics", `return [await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable(), await PublicKeyCredential.isConditionalMediationAvailable(), typeof Credential, PublicKeyCredential.prototype instanceof Credential, typeof PasswordCredential, typeof FederatedCredential];`, `[false,false,"function",true,"function","function"]`},
		{"PaymentRequest", `const req = new PaymentRequest([{ supportedMethods: 'https://pay.example/m' }], { total: { label: 't', amount: { currency: 'USD', value: '9.99' } } }, { requestShipping: true }); const out = [req instanceof PaymentRequest, req instanceof EventTarget, typeof req.id, req.shippingAddress, req.shippingOption, req.shippingType, await req.canMakePayment(), await req.hasEnrolledInstrument()]; try { await req.show(); } catch (e) { out.push(e.name); } try { await req.show(); } catch (e) { out.push(e.name); } try { await req.abort(); } catch (e) { out.push(e.name); } return out;`, `[true,true,"string",null,null,"shipping",false,false,"NotSupportedError","InvalidStateError","InvalidStateError"]`},
		{"PaymentRequest validation", `const ok = [{ supportedMethods: 'basic-card' }]; const total = { label: 't', amount: { currency: 'USD', value: '1.00' } }; const out = []; for (const f of [() => new PaymentRequest([], { total }), () => new PaymentRequest(ok, {}), () => new PaymentRequest(ok, { total: { label: 't', amount: { currency: 'US', value: '1' } } }), () => new PaymentRequest(ok, { total: { label: 't', amount: { currency: 'USD', value: 'abc' } } }), () => new PaymentRequest(ok, { total: { label: 't', amount: { currency: 'USD', value: '-1' } } }), () => new PaymentRequest(ok), () => PaymentRequest(ok, { total })]) { try { f(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError","RangeError","TypeError","TypeError","TypeError","TypeError"]`},
		{"PaymentRequest id and events", `const req = new PaymentRequest([{ supportedMethods: 'x' }], { id: 'order-1', total: { label: 't', amount: { currency: 'EUR', value: '5' } } }); let n = 0; req.onshippingaddresschange = () => n++; req.dispatchEvent(new Event('shippingaddresschange')); return [req.id, n, typeof PaymentResponse, typeof PaymentRequestUpdateEvent];`, `["order-1",1,"function","function"]`},
		{"storage access", `return [await document.hasStorageAccess(), await document.requestStorageAccess()];`, `[true,null]`},
		{"trusted types policies", `const p = trustedTypes.createPolicy('p1', { createHTML: (s, a) => '<b>' + s + (a || '') + '</b>', createScriptURL: s => s.toUpperCase() }); const h = p.createHTML('x', '!'); const u = p.createScriptURL('/a.js'); const sh = x => x.replace(/[<>]/g, '#'); const out = [p.name, sh(String(h)), sh(h + ''), sh(JSON.stringify(h)), trustedTypes.isHTML(h), trustedTypes.isHTML('x'), trustedTypes.isScript(h), trustedTypes.isScriptURL(u), String(u), h instanceof TrustedHTML, trustedTypes instanceof TrustedTypePolicyFactory, p instanceof TrustedTypePolicy]; try { p.createScript('1'); } catch (e) { out.push(e.name); } return out;`, `["p1","#b#x!#/b#","#b#x!#/b#","\"#b#x!#/b#\"",true,false,false,true,"/A.JS",true,true,true,"TypeError"]`},
		{"trusted types defaults and sinks", `const e = trustedTypes.emptyHTML; const before = trustedTypes.defaultPolicy; trustedTypes.createPolicy('default', { createHTML: s => s }); let dup; try { trustedTypes.createPolicy('default', {}); } catch (x) { dup = x.name; } const t = document.createElement('div'); t.innerHTML = trustedTypes.createPolicy('q', { createHTML: s => s }).createHTML('<i>k</i>'); return [String(e), before, trustedTypes.defaultPolicy.name, dup, t.innerHTML.replace(/[<>]/g, '#'), trustedTypes.getAttributeType('script', 'src'), trustedTypes.getAttributeType('a', 'href'), trustedTypes.getPropertyType('div', 'innerHTML'), trustedTypes.getAttributeType('div', 'onclick'), String(trustedTypes.emptyScript)];`, `["",null,"default","TypeError","#i#k#/i#","TrustedScriptURL",null,"TrustedHTML","TrustedScript",""]`},
		{"trusted types policy rule errors", `const p = trustedTypes.createPolicy('nullish', { createHTML: () => null }); const out = []; try { p.createHTML('x'); } catch (e) { out.push(e.name); } try { trustedTypes.createPolicy('bad', { createHTML: 5 }); } catch (e) { out.push(e.name); } try { new TrustedHTML(); } catch (e) { out.push(e.name); } return out;`, `["TypeError","TypeError","TypeError"]`},
		{"picture in picture", `const v = document.createElement('video'); const out = [document.pictureInPictureEnabled, document.pictureInPictureElement, v.disablePictureInPicture]; v.disablePictureInPicture = true; out.push(v.hasAttribute('disablepictureinpicture')); try { await v.requestPictureInPicture(); } catch (e) { out.push(e.name); } try { await document.exitPictureInPicture(); } catch (e) { out.push(e.name); } out.push(typeof PictureInPictureWindow, typeof PictureInPictureEvent); return out;`, `[false,null,false,true,"NotSupportedError","InvalidStateError","function","function"]`},
		{"PictureInPictureWindow shape", `try { new PictureInPictureWindow(); } catch (e) { return [e.name, PictureInPictureWindow.prototype instanceof EventTarget, new PictureInPictureEvent('enterpictureinpicture', { pictureInPictureWindow: Object.create(PictureInPictureWindow.prototype) }).type]; }`, `["TypeError",true,"enterpictureinpicture"]`},
	})
}
